// Reduce a catalog OR schedule/HAC course code to a stable lookup core:
// drop the section suffix, the catalog year suffix (Y/YR/Y12/Y22), and a
// schedule semester letter (A=S1 / B=S2).
export function coreCode(code) {
  let c = String(code || "").toUpperCase().replace(/\s+/g, "").split("-")[0]
  c = c.replace(/Y(R|\d*)$/, "")
  c = c.replace(/(A|B)$/, "")
  return c
}

// Friendly course name for a HAC/schedule code, or null if not in the catalog.
export function courseNameFromCode(code) {
  if (!code) return null
  return COURSE_CATALOG[coreCode(code)] || null
}
